import{_ as a,o,c as s,a3 as t}from"./chunks/framework.IBRwS0-4.js";const m=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),r={name:"explanation/concepts.md"};function i(n,e,c,d,p,l){return o(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The domain vocabulary, each term defined once. Wire shapes live in <a href="./../reference/">Reference</a>.</p><h2 id="session-ir" tabindex="-1">Session IR <a class="header-anchor" href="#session-ir" aria-label="Permalink to &quot;Session IR&quot;">​</a></h2><p>The canonical intermediate representation every agent store maps onto: nodes, messages, tool calls, checkpoints, metadata. Lossy edges are marked <code>lossy</code> rather than silently dropped. Shape: <a href="./../reference/session-formats.html">Session formats</a>.</p><h2 id="store-driver" tabindex="-1">Store driver <a class="header-anchor" href="#store-driver" aria-label="Permalink to &quot;Store driver&quot;">​</a></h2><p>A <code>sepia-driver-&lt;id&gt;</code> binary speaking ndjson JSON-RPC over stdio — the <code>SessionRepository</code> for one agent&#39;s on-disk store (Devin&#39;s SQLite, Cline&#39;s dirs, Claude&#39;s JSONL, Cursor&#39;s storage). Drivers are discovered, never linked; see <a href="./architecture.html#drivers-are-binaries-not-libraries">Architecture</a>.</p><h2 id="session-plane-controlplane" tabindex="-1">Session plane / ControlPlane <a class="header-anchor" href="#session-plane-controlplane" aria-label="Permalink to &quot;Session plane / ControlPlane&quot;">​</a></h2><p><code>sepia-session</code> — the local composition: attach modes, lock probes, prompt/cancel/permission, restore/rewind, <code>local::build</code>. <code>sepia serve</code> exposes it as the service wire.</p><h2 id="sepia-serve" tabindex="-1"><code>sepia serve</code> <a class="header-anchor" href="#sepia-serve" aria-label="Permalink to &quot;`sepia serve`&quot;">​</a></h2><p>The embedding surface: ndjson JSON-RPC on stdio. <code>manifest</code> negotiates protocol versions; <code>sessions.*</code>, <code>agents.*</code>, <code>config.*</code> and the <code>*.subscribe</code> feeds cover the plane; <code>session.event</code> / <code>node.event</code> notifications stream live events. Full table: <a href="./../reference/serve-wire.html">Serve wire</a>.</p><h2 id="sessions-prompt-wait" tabindex="-1"><code>sessions.prompt_wait</code> <a class="header-anchor" href="#sessions-prompt-wait" aria-label="Permalink to &quot;`sessions.prompt_wait`&quot;">​</a></h2><p>The blocking turn primitive — prompt → await terminal state → <code>PromptWaitResult</code> (<code>stopReason</code>/<code>text</code>/<code>timedOut</code>). Requests dispatch concurrently so <code>cancel</code>/<code>permission</code> interleave with an in-flight wait. Rides the entity plane as the <code>sepia.prompt_wait</code> op.</p><h2 id="agentconfig-ir" tabindex="-1">AgentConfig IR <a class="header-anchor" href="#agentconfig-ir" aria-label="Permalink to &quot;AgentConfig IR&quot;">​</a></h2><p>The typed model for agent configuration — skills, rules, commands, hooks, subagents — that <code>sepia config</code> ops and <code>type: sepia-config</code> tamias packs share. See <a href="./../reference/agent-configs.html">Agent configs</a>.</p><h2 id="overlay-store-sepia-meta" tabindex="-1">Overlay store (<code>sepia-meta</code>) <a class="header-anchor" href="#overlay-store-sepia-meta" aria-label="Permalink to &quot;Overlay store (`sepia-meta`)&quot;">​</a></h2><p>Sepia-owned per-session metadata — title/pin/projectIds/spans — kept as a JSON file beside the read-only agent stores. Agent stores are never written by metadata ops.</p><h2 id="the-sepia-command" tabindex="-1">The <code>sepia</code> command <a class="header-anchor" href="#the-sepia-command" aria-label="Permalink to &quot;The `sepia` command&quot;">​</a></h2><p>A tamias <code>bins[]</code> shim over <code>tamias-driver-sepia</code> — no hand-rolled binary. The driver derives an ops manifest from the clap tree (<code>cli.&lt;verb&gt;</code> queries, <code>run</code>/<code>cli</code> passthroughs) and serves the pavo views plus an optional MCP surface.</p>',18)])])}const f=a(r,[["render",i]]);export{m as __pageData,f as default};
